def kind_param(kinds):
    text = " ".join(f"{k}: {v}" for k, v in kinds.items())
    return {"type": "string", "enum": list(kinds), "description": "What the caller said. " + text}


def task(step):
    return ("NEXT STEP: {{guide}}\n\n" + step + " Call the tool of this step with every caller message, then do NEXT STEP. "
            "If the caller asks a short question, answer in one sentence with no figure, then do NEXT STEP.")


