HELPERS = r'''
import json
LINES = %(lines)r
MONTHS = %(months)r
CUR = %(cur)r
MAX_TRIES = %(tries)d
CALM = %(calm)d
MAX_WORDS = %(words)d
DIGIT_WORDS = ['sıfır', 'bir', 'iki', 'üç', 'dört', 'beş', 'altı', 'yedi', 'sekiz', 'dokuz']
def load(name):
    v = vars.get(name + '_response.data.raw')
    if isinstance(v, str):
        try:
            v = json.loads(v)
        except Exception:
            v = None
    return v if isinstance(v, dict) else dict()
def ok(name):
    return str(vars.get(name + '_response.data.ok')) == 'true'
def num(x):
    try:
        return float(x)
    except Exception:
        return 0.0
def tdate(s):
    s = str(s or '')
    if len(s) != 10:
        return ''
    return str(int(s[0:2])) + ' ' + MONTHS[int(s[3:5]) - 1] + ' ' + s[6:10]
def iso(s):
    s = str(s or '')
    return s[6:10] + '-' + s[3:5] + '-' + s[0:2] if len(s) == 10 else ''
def money(x, unit, sub):
    x = round(num(x), 2)
    whole = int(abs(x))
    cents = int(round((abs(x) - whole) * 100))
    text = '{:,}'.format(whole).replace(',', '.') + ' ' + unit
    if cents:
        text = text + ' ' + str(cents) + ' ' + sub
    return text
def spell(d):
    return ' '.join(DIGIT_WORDS[int(c)] for c in str(d) if c.isdigit())
def safe_name(n):
    n = str(n or '').strip()
    if not n or len(n.split()) > MAX_WORDS or len(n) > 40 or any(c in n for c in ':;<>[]()') or any(c.isdigit() for c in n):
        return ''
    return n
def tr_lower(s):
    return str(s or '').replace('İ', 'i').replace('I', 'ı').lower().strip()
def join_tr(items):
    return items[0] if len(items) == 1 else ', '.join(items[:-1]) + ' ve ' + items[-1]
def cards():
    try:
        return json.loads(vars.get('cards_json') or '[]')
    except Exception:
        return []
def eligible():
    return [c for c in cards() if c['main']]
def say(line):
    vars['last_line'] = line
    vars['guide'] = 'Say exactly: "' + line + '"'
def ask_again(line):
    n = int(num(vars.get('tries'))) + 1
    vars['tries'] = n
    if n >= MAX_TRIES:
        vars['route'] = 'close_tries'
    else:
        say(line)
def names_line():
    names = []
    for c in eligible():
        nm = c['name'] or ('sonu ' + spell(c['last4']) + ' ile biten kart')
        if nm not in names:
            names.append(nm)
    return join_tr(names) if names else ''
def pick_line():
    names = []
    for c in eligible():
        if c['name'] and c['name'] not in names:
            names.append(c['name'])
    if len(names) >= 2:
        return LINES['pick_card'].format(a=names[0], b=names[1])
    if names:
        return LINES['pick_card_one'].format(a=names[0])
    return LINES['pick_card_one'].format(a='sonu ' + spell(eligible()[0]['last4']) + ' ile biten kart')
def common(kind):
    """Exits and interruptions that hold at every question. True when handled."""
    routes = dict(pay='close_pay', agent='close_agent', dispute='close_dispute', other_person='close_security',
                  not_turkish='close_not_turkish', change_topic='close_menu')
    if kind in routes:
        vars['route'] = routes[kind]
        return True
    if kind == 'outside':
        vars['outside_pending'] = 'yes'
        say(LINES['outside_ask'])
        return True
    if kind == 'menu_yes' and vars.get('outside_pending') == 'yes':
        vars['route'] = 'close_outside'
        return True
    if kind == 'stay':
        vars['outside_pending'] = 'no'
        vars['guide'] = 'Say exactly: "' + str(vars.get('last_line') or '') + '"'
        return True
    if kind == 'angry':
        n = int(num(vars.get('calm_count'))) + 1
        vars['calm_count'] = n
        if n > CALM:
            vars['route'] = 'close_agent'
        else:
            say(LINES['calm'] + ' ' + str(vars.get('last_line') or ''))
        return True
    if kind == 'secret':
        say(LINES['no_pin'] + ' ' + str(vars.get('last_line') or ''))
        return True
    if kind == 'repeat':
        vars['guide'] = 'Say again exactly: "' + str(vars.get('last_line') or '') + '"'
        return True
    if kind == 'silence':
        n = int(num(vars.get('silence_count'))) + 1
        vars['silence_count'] = n
        if n >= 3:
            vars['route'] = 'close_silence'
        else:
            vars['guide'] = 'Say exactly: "' + str(vars.get('last_line') or '') + '"'
        return True
    return False
''' % {"lines": L, "months": SPEC["months"], "cur": SPEC["currencies"], "tries": SPEC["max_tries"],
       "calm": SPEC["calming_replies"], "words": SPEC["max_name_words"]}

# The post-hooks write ok and the whole service data as JSON; code nodes read <node>_response.data.raw.
def post(extra=""):
    return ("import json\nr = d.get('result') or dict()\nx = d.get('data') or dict()\n"
            "good = str(r.get('returnCode')) == '1'" + extra + "\n"
            "d['ok'] = 'true' if good else 'false'\nd['raw'] = json.dumps(x)")

POST_PLAIN = post()
