    "agent": "asks for a person or a customer representative.",
    "dispute": "says the debt is wrong, or that a payment they made does not show.",
    "other_person": "asks about the card or debt of another person (a spouse, a parent, a child).",
    "outside": "asks about a topic this line does not handle: interest rates, limits, points, instalments, loans, blocking a card, branch hours, or a figure such as next month's bill.",
    "menu_yes": "says yes to the question whether to go to the main menu.",
    "stay": "says no to the question whether to go to the main menu, and wants to go on.",
    "change_topic": "wants to do a different transaction now (for example their limit).",
    "angry": "is upset, shouts or swears, with no answer to the question.",
    "secret": "says a PIN, a password or a one-time code without being asked.",
    "repeat": "asks you to say the last thing again.",
    "not_turkish": "speaks a language that is not Turkish.",
    "silence": "the message is empty or only silence.",
}


def kind_param(kinds):
    text = " ".join(f"{k}: {v}" for k, v in kinds.items())
    return {"type": "string", "enum": list(kinds), "description": "What the caller said. " + text}


def task(step):
    return ("NEXT STEP: {{guide}}\n\n" + step + " Call the tool of this step with every caller message, then do NEXT STEP. "
            "If the caller asks a short question, answer in one sentence with no figure, then do NEXT STEP.")


card_said = state_tool("card_said", "CALL it with every caller message while the card is chosen.", {
    "kind": kind_param({"card": "names a card or says digits of a card.", "all_cards": "wants the debt of all cards at once.",
                        "done": "wants nothing more or says goodbye.", **KINDS_COMMON,
                        "unclear": "anything else, also a mumble or a cut-off message."}),
    "name": {"type": "string", "description": "The card name the caller said, as said, or empty."},
    "digits": {"type": "string", "description": "The card digits the caller said, as digits only (e.g. 4253), or empty."}},
    CARD_SAID)
after_said = state_tool("after_said", "CALL it with every caller message after the debt reading.", {
    "kind": kind_param({"yes": "a plain yes.", "no": "a plain no.", "another_yes": "wants the debt of another of their cards.",
                        "another_no": "does not want another card.", "email": "wants the statement sent by e-mail.",
                        "email_old": "wants an earlier statement, a paper copy, or an e-mail to another address.",
                        "week_change": "wants to change the statement date or week.",
                        "done": "wants nothing more, says thank you or goodbye.", **KINDS_COMMON,
                        "unclear": "anything else."}),
    "week": {"type": "string", "description": "The week of the month the caller named, 1 to 4, or empty."}}, AFTER_SAID)
email_said = state_tool("email_said", "CALL it with every caller message while the e-mail is confirmed.", {
    "kind": kind_param({"yes": "a clear yes to sending, with no change.", "no": "a no.",
                        "not_mine": "says the address is no longer theirs.",
                        "other_address": "wants another address, an earlier statement or a paper copy.", **KINDS_COMMON,
                        "unclear": "anything else, also a hedge."})}, EMAIL_SAID)
week_said = state_tool("week_said", "CALL it with every caller message while the statement week is changed.", {
    "kind": kind_param({"yes": "a clear 'evet' with no hedge and no change.", "no": "a no.",
                        "week": "names a week of the month (1 to 4).",
                        "hedge": "a vague answer such as 'olur herhalde', 'galiba', 'sanırım'.", **KINDS_COMMON,
                        "unclear": "anything else, also a day or a date."}),
    "week": {"type": "string", "description": "The week of the month named, as a digit 1 to 4, or empty."}}, WEEK_SAID)

# ---------------------------------------------------------------- tools and nodes

list_tool = make_tool(API, "cards_list", baked={"customerNo": CUST, "aiFlow": SPEC["ai_flow"], "lang": "tr", "ani": ""},
                      post_code=POST_PLAIN)
bal_tool = make_tool(API, "cards_balance", baked={"cardNumber": "{{sel_card}}", "lang": "tr", "ani": ""}, post_code=POST_PLAIN)
mail_tool = make_tool(API, "contact_email_get", baked={"customerNo": CUST, "intAddressInfoType": SPEC["address_type"],
                                                       "lang": "tr", "ani": ""}, post_code=POST_PLAIN)
weekget_tool = make_tool(API, "statement_week_get", baked={"cardNumber": "{{sel_card}}", "lang": "tr", "ani": ""},
                         post_code=POST_PLAIN)
decide_tool = make_tool(API, "statement_week_decide", baked={"cardNumber": "{{sel_card}}", "newStatementWeek": "{{week_new}}",
                                                             "statementDay": "{{week_day}}", "lang": "tr", "ani": ""},
                        post_code=POST_PLAIN)
change_tool = make_tool(API, "statement_week_change", baked={"cardNumber": "{{sel_card}}", "newStatementWeek": "{{week_new}}",
                                                             "statementDay": "{{week_day}}", "lang": "tr", "ani": ""},
                        post_code=POST_WEEK)
pdf_tool = make_tool(API, "statement_pdf_send", baked={"customerNo": CUST, "cardNumber": "{{sel_card}}",
                                                       "currencyType": "{{pdf_currency}}", "statementDate": "{{sel_stmt_date}}",
                                                       "emailAddress": "{{email_addr}}", "lang": "tr", "ani": ""},
                     post_code=POST_PDF)

CLOSES = dict(SPEC["closes"])
CLOSES["close_not_mine"] = L["address_change"] + " " + CLOSES["close_menu"]
closes = []
for key, goodbye in CLOSES.items():
    closes += close_sequence(key, {"close_key": key}, goodbye)


def routes(*targets):
    return [go(t, any_of(cond("route", "equals", t)), t) for t in list(targets) + list(CLOSES)]


def talk(name, step, tool, say_line, targets):
    return conversation(name, task(step), tools=[tool], on_enter=tts(say_line), max_turns=30,
                        max_turn_target="close_tries", transitions=routes(*targets))


FALL = {"route": "close_error", "guide": "Say nothing new."}
nodes = [
    start("setup"),
    code_node("setup", SETUP, "list_cards"),
    api_node("list_cards", list_tool, "cards_prep"),
    code_node("cards_prep", CARDS_PREP, "close_error", transitions=routes("choose_card", "get_balance"), fallbacks=FALL),
    talk("choose_card", "The caller has several cards. Find out which card they mean.", card_said, "{{pick_line}}",
         ["get_balance"]),
    api_node("get_balance", bal_tool, "reading"),
    code_node("reading", READING, "close_error", transitions=routes("contact_get"), fallbacks=FALL),
    api_node("contact_get", mail_tool, "offer_prep"),
    code_node("offer_prep", OFFER_PREP, "after", fallbacks={"after_say": "{{reading}}", "guide": "Wait for the answer."}),
    talk("after", "You read the debt and asked what the caller wants next.", after_said, "{{after_say}}",
         ["choose_card", "email_confirm", "week_get"]),
    talk("email_confirm", "You asked whether to send the latest statement to the registered address.", email_said,
         "{{email_line}}", ["send_pdf"]),
    *record_with_retry("send_pdf", pdf_tool, 1, "close_email_sent", "close_error"),
    api_node("week_get", weekget_tool, "week_prep"),
    code_node("week_prep", WEEK_PREP, "close_week_error", transitions=routes("week_talk", "week_decide"),
              fallbacks={"route": "close_week_error", "week_say": ""}),
    talk("week_talk", "You are changing the statement week of the card.", week_said, "{{week_say}}", ["week_decide"]),
    api_node("week_decide", decide_tool, "decide_prep"),
    code_node("decide_prep", DECIDE_PREP, "close_week_error", transitions=routes("week_confirm"),
              fallbacks={"route": "close_week_error", "week_confirm_line": "", "week_done_line": ""}),
    talk("week_confirm", "You read the new dates and asked for a clear yes.", week_said, "{{week_confirm_line}}",
         ["week_decide", "week_write"]),
    *record_with_retry("week_write", change_tool, 1, "close_week_done", "close_week_error"),
] + closes

test_vars = {k: v for k, v in SPEC["sample_vars"].items() if k in V.values()}
WORKFLOW = workflow("start", SYSTEM, nodes, test_variables=test_vars)

if __name__ == "__main__":
    json.dump(WORKFLOW, open("workflow.json", "w"), indent=1, ensure_ascii=False)
    print("wrote workflow.json:", len(WORKFLOW["nodes"]), "nodes")

